contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount1, uint amount2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount1) + (amount2)); require(amount1 <= 1000000000000000000000000000000); require(amount2 <= 1000000000000000000000000000000);
        require(amount1 == 10 && amount2 == 10, "amounts must be 10");
        require(address(this).balance >= amount1 + amount2, "insufficient balance");

        bool reverted1;
        c.play{value: amount1}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted1 = true;
        } else {
            reverted1 = false;
        }

        bool reverted2;
        c.play{value: amount2}(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            reverted2 = true;
        } else {
            reverted2 = false;
        }

        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;

        assert(!reverted1 && !reverted2 && (potAfter == 0 || potAfter == 20));
    }

    receive() external payable {}
}

