pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount1, uint256 amount2) internal {
        amount1 = bound(amount1, 0, 1000000000000000000000000000000);
        amount2 = bound(amount2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        amount1 = 10;
        amount2 = 10;
        vm.assume(address(this).balance >= amount1 + amount2);
        bool reverted1;
        try c.play{value: amount1}() {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }
        bool reverted2;
        try c.play{value: amount2}() {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        assertTrue(!reverted1 && !reverted2 && (potAfter == 0 || potAfter == 20));
    }

    function testFuzz_run(uint256 amount1, uint256 amount2) public {
        _run(amount1, amount2);
    }

    receive() external payable {}
}
